// handleSpeak synthesizes speech using AWS Polly Neural voices
func (s *Server) handleSpeak(w http.ResponseWriter, r *http.Request) {
	text := r.URL.Query().Get("text")
	if text == "" {
		http.Error(w, "Text parameter is required", http.StatusBadRequest)
		return
	}

	ctx := context.TODO()
	cfg, err := config.LoadDefaultConfig(ctx)
	if err != nil {
		http.Error(w, "Failed to load AWS configuration: "+err.Error(), http.StatusInternalServerError)
		return
	}

	pollyClient := polly.NewFromConfig(cfg)
	input := &polly.SynthesizeSpeechInput{
		Engine:       ptypes.EngineNeural,
		OutputFormat: ptypes.OutputFormatMp3,
		Text:         aws.String(text),
		VoiceId:      ptypes.VoiceIdMatthew,
	}

	output, err := pollyClient.SynthesizeSpeech(ctx, input)
	if err != nil {
		log.Printf("AWS Polly synthesis failed: %v. Fallback to client-side SpeechSynthesis.", err)
		http.Error(w, "AWS Polly synthesis failed: "+err.Error(), http.StatusInternalServerError)
		return
	}
	defer output.AudioStream.Close()

	w.Header().Set("Content-Type", "audio/mpeg")
	w.WriteHeader(http.StatusOK)
	_, _ = io.Copy(w, output.AudioStream)
}
